package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	if !scanner.Scan() {
		return
	}
	n := 0
	fmt.Sscan(scanner.Text(), &n)

	o := n + 1
	array := make([]int, n)
	for i := 0; i < n; i++ {
		array[i] = i + 1
	}

	if !scanner.Scan() {
		return
	}
	m := 0
	fmt.Sscan(scanner.Text(), &m)

	for j := 0; j < m; j++ {
		if !scanner.Scan() {
			break
		}
		r := 0
		fmt.Sscan(scanner.Text(), &r)

		for l := r - 1; l < o-1; l++ {
			if l >= 0 && l < n {
				array[l] = r
			}
		}
		if r < o {
			o = r
		}
	}

	for i := 0; i < n; i++ {
		fmt.Print(array[i], " ")
	}
}

