package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	nextInt := func() int {
		scanner.Scan()
		val, _ := strconv.Atoi(scanner.Text())
		return val
	}

	n := nextInt()
	o := n + 1
	array := make([]int, n)
	for i := 0; i < n; i++ {
		array[i] = i + 1
	}

	m := nextInt()

	for j := 0; j < m; j++ {
		r := nextInt()
		for l := r - 1; l < o-1; l++ {
			array[l] = r
		}
		if r < o {
			o = r
		}
	}

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	for i := 0; i < n; i++ {
		fmt.Fprint(writer, array[i], " ")
	}
}

